                let who = null; try { const m = String(new Error().stack || '').split('\n').slice(2).join('\n').match(/gyx-plugin\/([^:)\s]+?)\.js/); /* 跳过第一行（Error）和第二行（这个包装函数自己） */ if (m) { try { who = decodeURIComponent(m[1]); } catch (e) { who = m[1]; } } } catch (e) {}
